'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const validSections=['scene','models','workflow','impact'];
function showSection(id,scroll=false){if(!validSections.includes(id))id='scene';$$('.panel').forEach(p=>p.hidden=p.id!==id);$$('[data-section]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.section===id)));const url=new URL(location.href);url.searchParams.set('s',id);history.replaceState(null,'',url);if(scroll)$('#explore').scrollIntoView({behavior:'smooth'});}
$$('[data-section]').forEach(b=>b.addEventListener('click',()=>showSection(b.dataset.section)));
if(/^#ref-\d+$/.test(location.hash))location.replace('references.html'+location.hash);else showSection(new URL(location.href).searchParams.get('s')||'scene');
function updateBrief(){const world=$('#world'),mood=$('#mood'),camera=$('#camera');['city','forest','space'].forEach(id=>$('#'+id).toggleAttribute('hidden',id!==world.value));$('.storyboard').className='storyboard '+camera.value;$('#sky-top').setAttribute('stop-color',mood.value==='warm'?'#d5a56d':'#344b6a');$('#sky-bottom').setAttribute('stop-color',mood.value==='warm'?'#334e51':'#171e36');$('#brief').textContent=`A lone traveller pauses in ${world.selectedOptions[0].text.toLowerCase()}. ${mood.selectedOptions[0].text} atmosphere. ${camera.selectedOptions[0].text}. Keep the traveller’s appearance consistent; review the motion and continuity before using the shot.`;$('#copy-status').textContent='';}
$('#scene-form').addEventListener('change',updateBrief);updateBrief();$('#copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#brief').textContent);$('#copy-status').textContent='Shot brief copied.';}catch{$('#copy-status').textContent='Select and copy the brief below.';}});
const models={text:{color:'#dfb9d0',title:'Text predicts the next token, then repeats.',nodes:[['Split & embed','Turn text pieces into vectors with position information.'],['Attend & refine','Masked attention compares the available context; neural layers refine each token.'],['Choose & repeat','Predict a next-token distribution, select a token and append it.']],note:'A token can be a word or part of a word. The model predicts likely continuations; it does not verify their truth.',refs:[7,8]},image:{color:'#b8d6e3',title:'A diffusion model repeatedly cleans up a noisy latent.',nodes:[['Encode the prompt','Text embeddings guide the image’s subject and appearance.'],['Denoise repeatedly','A U-Net predicts a correction; a sampler updates the latent over many steps.'],['Decode the image','A VAE decoder turns the refined latent into visible pixels.']],note:'This describes latent diffusion with a U-Net. Other image generators use different architectures, including diffusion Transformers and GANs.',refs:[2]},video:{color:'#c3d5ad',title:'Video models refine a clip across space and time.',nodes:[['Prompt + optional image','A text prompt and, for image-to-video, a reference image condition the clip.'],['Refine the clip latent','A video diffusion Transformer models relationships across space and time as the sampler updates it.'],['Decode frames','A video VAE decodes the clip latent into frames that can be played as video.']],note:'Wan-style video diffusion is not simply an image model guessing one frame after another. Frames are refined with temporal context.',refs:[3,9]},audio:{color:'#e7d591',title:'MusicGen predicts audio tokens, then decodes sound.',nodes:[['Describe the music','Text—and optionally a melody—conditions generation.'],['Predict audio codes','A Transformer predicts sequences of compressed audio-codebook tokens.'],['Decode sound','An audio codec decoder converts those tokens into a waveform.']],note:'MusicGen is an autoregressive example. Speech and other music systems can use different designs. Check the model’s licence before commercial use.',refs:[4,14]}};
const citations=refs=>refs.map(n=>`<a href="references.html#ref-${n}">[${n}] →</a>`).join(' ');
function showModel(id){const m=models[id];$$('[data-model]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.model===id)));$('#model-detail').innerHTML=`<p class="model-summary"><strong>${m.title}</strong></p><div class="model-chain" style="--tint:${m.color}">${m.nodes.map(([a,b])=>`<div class="node"><b>${a}</b><span>${b}</span></div>`).join('')}</div><p>${m.note}</p><p class="source-note">Grounding sources ${citations(m.refs)}</p>`;}
$$('[data-model]').forEach(b=>b.addEventListener('click',()=>showModel(b.dataset.model)));showModel('text');
const posterWorkflow=["In ComfyUI, you can use nodes with “connection points,” like in UE5, to pass the previous node’s content to the next. [3]", "Generating an image to use as the first frame of the video could guide the video generation process (Wan 2.2). [3]", "Samplers define how the model is used, accompanied on the right by the video output in ComfyUI. [3]", "Finalized clips and audio are then stitched together using apps like DaVinci Resolve (film), Final Cut Pro (movie) and Logic Pro (audio). [13,24,25]", "For commercial use, some companies distribute AI-generated videos without monetisation for the specific clip. This is due to either the video-generation platform’s policy or an ethical promise. [10,14,17]", "“The Frost” (2023) is one of the first well-known examples of AI-generated film that matched human-level film production. It includes a video player, credits and AI disclosures. [11]"];
const steps=[['Write the story','A premise, audience and creative constraints.','A reviewed script, shot list and prompts.','Use language-model suggestions as drafts. People choose the story and verify details.',[1,7]],['Create visual assets','Shot prompts and a chosen visual direction.','Concept art, character references and a possible first frame.','Reference images can guide appearance, but do not guarantee consistency across a film.',[1,2,3]],['Generate the video','Text conditioning, optional reference image, model and sampler settings.','Candidate video clips.','In ComfyUI, compatible node ports pass data between components. Inspect motion, camera control and continuity.',[3,9]],['Add sound & edit','Selected clips, dialogue, music and effects.','An edited sequence with sound, colour and captions.','Match sound to the picture; review pacing, licences and accessibility.',[1,4,14]],['Plan monetisation','A finished work and rights to its components.','A suitable route: commissions, licensing, sponsorship or eligible platform revenue.','AI generation is not a revenue guarantee. Clear permissions and check originality and platform rules.',[10,14]],['Distribute online','The reviewed film, thumbnail, credits and disclosures.','A published film and audience feedback.','Use appropriate synthetic-media labels. Learn from feedback without mistaking views for quality.',[10,16]]];
$('#steps').innerHTML=steps.map((s,i)=>`<button data-step="${i}" aria-pressed="${i===0}"><b>0${i+1}</b>${s[0]}</button>`).join('');
function showStep(i){const s=steps[i];$$('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.step)===i)));$('#step-detail').innerHTML=`<h3>0${i+1} / ${s[0]}</h3><dl><dt>Input</dt><dd>${s[1]}</dd><dt>Output</dt><dd>${s[2]}</dd></dl><p><strong>From our poster:</strong> ${posterWorkflow[i]}</p><p class="source-note">${citations(s[4])}</p>`;}
$$('[data-step]').forEach(b=>b.addEventListener('click',()=>showStep(Number(b.dataset.step))));showStep(0);
const cases={labour:{title:'A performer is scanned for a digital replica.',question:'The production wants to reuse the replica in another project. What should be clarified?',choices:['Treat the scan as unlimited permission','Agree on use, consent and compensation'],feedback:['A scan does not settle every question about future use. Performers and film workers have raised concerns about consent, pay and control.','Define the agreed use and compensation, and obtain the necessary consent. Keep the performer involved in decisions about their digital likeness.'],refs:[6,20]},trust:{title:'A realistic clip looks like a news event.',question:'An AI scene is shared without its original context. What is the responsible response?',choices:['Assume viewers can tell it is synthetic','Label it and preserve its context'],feedback:['Viewers may be uncertain rather than simply fooled. Research on political deepfakes found that this uncertainty can reduce trust in news.','State how it was made and what it depicts. Clear context helps people distinguish fiction from evidence of a real event.'],refs:[21,16]},consent:{title:'The scene uses a real person’s face.',question:'A convincing synthetic clip places someone in a scene they never agreed to. What should the team do?',choices:['Release it with an AI label','Stop and secure permission'],feedback:['A label does not replace consent. A synthetic depiction can still harm privacy and reputation.','Consent comes before release. Check permissions for the person’s likeness and the intended use; avoid harmful fabricated depictions.'],refs:[19,20]},quality:{title:'The hero’s prop changes between shots.',question:'The first frame matches your reference, but the next clip changes the object. What now?',choices:['Trust the reference image','Review, revise and edit'],feedback:['Reference conditioning helps guide generation, but it does not guarantee continuity.','Compare shots, revise prompts or inputs, regenerate selectively and edit around failures. Human review remains essential.'],refs:[1,3]},revenue:{title:'One template produces a hundred shorts.',question:'Can you assume that a channel of near-identical AI videos will earn advertising revenue?',choices:['Yes, more uploads mean revenue','Check originality and eligibility'],feedback:['Upload volume does not guarantee monetisation. Repetitive or mass-produced content can be ineligible.','Assess whether the work adds original value. YouTube’s policies address repetitive and mass-produced content, including AI-made material.'],refs:[10]}};
function showCase(id){const c=cases[id];$$('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===id)));$('#case-detail').innerHTML=`<h3>${c.title}</h3><p>${c.question}</p><div class="case-options">${c.choices.map((x,i)=>`<button data-answer="${i}" aria-pressed="false">${x}</button>`).join('')}</div><div id="case-feedback" class="feedback" hidden></div><p class="source-note">Grounding sources ${citations(c.refs)}</p>`;$$('[data-answer]').forEach(b=>b.addEventListener('click',()=>{$$('[data-answer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#case-feedback').hidden=false;$('#case-feedback').textContent=c.feedback[Number(b.dataset.answer)];}));}
$$('[data-case]').forEach(b=>b.addEventListener('click',()=>showCase(b.dataset.case)));showCase('consent');
